"""Tests for the static dashboard site (run `make test` to build + test)."""
from __future__ import annotations

import re
import xml.etree.ElementTree as ET
from pathlib import Path

import pytest

from sitegen.build import DIST, main as build_main
from sitegen.data import REGION_KEYS, generate, region_total

SVG_NS = "{http://www.w3.org/2000/svg}"
EXTERNAL_SCHEMES = ("http://", "https://", "mailto:", "//")


@pytest.fixture(scope="session", autouse=True)
def dist() -> Path:
    build_main()
    return DIST


def pages(dist: Path) -> list[Path]:
    return sorted(dist.rglob("*.html"))


def region_pages(dist: Path) -> dict[str, str]:
    return {slug: (dist / f"{slug}.html").read_text(encoding="utf-8") for slug in REGION_KEYS}


# --- site layout -----------------------------------------------------------


def test_exactly_four_html_files(dist: Path):
    found = sorted(p.relative_to(dist).as_posix() for p in dist.rglob("*.html"))
    assert found == ["apac.html", "emea.html", "index.html", "na.html"]


def test_no_broken_internal_links(dist: Path):
    checked = 0
    for page in pages(dist):
        text = page.read_text(encoding="utf-8")
        for url in re.findall(r'href="([^"]*)"', text):
            if url.startswith(EXTERNAL_SCHEMES) or url.startswith("#"):
                continue
            target = (page.parent / url.split("#", 1)[0]).resolve()
            assert target.is_file(), f"{page.name}: broken internal link {url!r}"
            assert DIST.resolve() in target.parents, f"{page.name}: {url!r} escapes dist/"
            checked += 1
    assert checked >= 4  # index links to 3 regions; each region links back


# --- numbers ---------------------------------------------------------------


def _cell(html_text: str, cell_id: str) -> float:
    m = re.search(rf'<td class="num" id="{re.escape(cell_id)}">([0-9.]+)</td>', html_text)
    assert m, f"missing cell #{cell_id}"
    return float(m.group(1))


def test_region_totals_match_index_rollup_within_a_cent(dist: Path):
    index_html = (dist / "index.html").read_text(encoding="utf-8")
    for slug, page_html in region_pages(dist).items():
        rollup = _cell(index_html, f"rollup-{slug}")
        page_total = _cell(page_html, "region-total")
        assert abs(rollup - page_total) < 0.01, (
            f"{slug}: index rollup {rollup} vs region total {page_total}"
        )


def test_totals_match_generated_data(dist: Path):
    data = generate()
    for slug, page_html in region_pages(dist).items():
        expected = region_total(data[slug])
        assert abs(_cell(page_html, "region-total") - expected) < 0.01


# --- SVG bar chart ---------------------------------------------------------


def test_bar_charts_have_12_proportional_bars(dist: Path):
    data = generate()
    for slug, page_html in region_pages(dist).items():
        root = ET.fromstring(page_html)
        bars = [r for r in root.iter(f"{SVG_NS}rect") if r.get("class") == "bar"]
        assert len(bars) == 12, f"{slug}: expected 12 bars, got {len(bars)}"
        heights = [float(r.get("height")) for r in bars]
        revs = [w["revenue"] for w in data[slug]["weeks"]]

        # ratio of two known bars (weeks 0 and 1) within 1e-6
        i, j = 0, 1
        assert abs(heights[i] / heights[j] - revs[i] / revs[j]) <= 1e-6

        # and the extreme bars too (tallest vs shortest week)
        hi, lo = max(range(12), key=lambda k: revs[k]), min(range(12), key=lambda k: revs[k])
        assert abs(heights[hi] / heights[lo] - revs[hi] / revs[lo]) <= 1e-6

        # tallest bar is exactly the scale reference
        assert abs(max(heights) - max(revs) / max(revs) * max(heights)) <= 1e-6


# --- document structure / well-formedness ----------------------------------


def test_every_page_has_one_h1_and_meta_charset_and_is_well_formed(dist: Path):
    for page in pages(dist):
        text = page.read_text(encoding="utf-8")
        h1s = re.findall(r"<h1[\s>]", text)
        assert len(h1s) == 1, f"{page.name}: expected exactly one <h1>, got {len(h1s)}"
        assert re.search(r'<meta charset="utf-8"\s*/>', text), f"{page.name}: missing charset"
        try:
            ET.fromstring(text)
        except ET.ParseError as exc:
            pytest.fail(f"{page.name}: not well-formed XHTML: {exc}")
